#createWaitingHandler (handler) {
  /** @type {WaitingHandler} */
  const waitingHandler = {
    handler,
    controller: null,
    bufferedChunks: [],
    bufferedBytes: 0,
    pendingTrailers: null,
    done: false
  }

  const state = {
    aborted: false,
    paused: false,
    reason: null
  }

  waitingHandler.controller = {
    resume: () => {
      if (state.aborted) {
        return
      }

      state.paused = false
