'use strict'

const { createInflate, createGunzip, createBrotliDecompress, createZstdDecompress } = require('node:zlib')
const { pipeline, Transform: TransformStream } = require('node:stream')
const { InvalidArgumentError, ResponseExceededMaxSizeError } = require('../core/errors')
const DecoratorHandler = require('../handler/decorator-handler')

/** @typedef {import('node:stream').Transform} Transform */
/** @typedef {import('node:stream').Transform} Controller */
/** @typedef {Transform&import('node:zlib').Zlib} DecompressorStream */

/** @type {Record<string, () => DecompressorStream>} */
const supportedEncodings = {
  __proto__: null,
  gzip: createGunzip,
  'x-gzip': createGunzip,
  br: createBrotliDecompress,
  deflate: createInflate,
  compress: createInflate,
  'x-compress': createInflate,
  zstd: createZstdDecompress
}

const defaultSkipStatusCodes = /** @type {const} */ ([204, 304])
// Size policy belongs to the application, not to the transport. Backpressure
// keeps the amount of buffered decoded output tied to consumer demand, so no
// limit is needed to bound memory. `maxSize` stays available as an opt-in
// circuit breaker for callers that do want to cap a decoded body.
const defaultMaxSize = 0

/**
 * Limits the output of one stage in a decompression chain.
 * @param {number} maxSize - Maximum output size in bytes
 * @returns {Transform}
 */
function createMaxSizeLimiter (maxSize) {
  let size = 0

  return new TransformStream({
    transform (chunk, _encoding, callback) {
      const decompressedSize = size + chunk.length
      if (decompressedSize > maxSize) {
        callback(new ResponseExceededMaxSizeError(
          `Decompressed response size (${decompressedSize}) exceeded maxSize (${maxSize})`
        ))
        return
      }

      size = decompressedSize
      callback(null, chunk)
    }
  })
}

/**
 * The controller handed to the downstream handler while a response is being
 * decoded.
 *
 * Decompression splits one flow-controlled stream into two: the compressed
 * bytes arriving from the transport, and the decoded bytes leaving the decoder.
 * They pause for different reasons and must be tracked separately, so the
 * consumer gets this proxy instead of the transport controller. Its pause
 * state is owned by the consumer and lives in the handler, which leaves the
 * transport controller free to carry only the decoder's writable pressure --
 * a controller that is replaced on every retry, and whose pause state must not
 * be mistaken for the consumer's.
 *
