 * at all -- the proxy is inert and forwards flow control straight through.
 */
class DecompressController {
  /** @type {Controller|null} */
  target = null
  /** @type {boolean} */
  #paused = false
  /** @type {boolean} */
  #active = false
  /** @type {() => void} */
  #onPause
  /** @type {() => void} */
  #onResume

  /**
   * @param {() => void} onPause - Called when the consumer asks us to stop
   * @param {() => void} onResume - Called when the consumer asks for more
   */
  constructor (onPause, onResume) {
    this.#onPause = onPause
    this.#onResume = onResume
  }

  /**
   * Starts intercepting the consumer's flow control. Called once decompression
   * is known to be active for this response.
   * @returns {void}
   */
  activate () {
    this.#active = true
  }

  pause () {
    if (!this.#active) {
      this.target?.pause()
      return
    }

    if (!this.#paused) {
      this.#paused = true
      this.#onPause()
    }
  }

  resume () {
    if (!this.#active) {
      this.target?.resume()
      return
    }

    if (this.#paused) {
      this.#paused = false
      this.#onResume()
    }
  }

  get paused () {
    return this.#active ? this.#paused : (this.target?.paused ?? false)
  }

  abort (reason) {
    this.target?.abort(reason)
  }

  get aborted () {
    return this.target?.aborted ?? false
  }

  get reason () {
    return this.target?.reason ?? null
  }

  get rawHeaders () {
    return this.target?.rawHeaders ?? null
  }

  set rawHeaders (value) {
    if (this.target) {
      this.target.rawHeaders = value
    }
  }

  get rawTrailers () {
    return this.target?.rawTrailers ?? null
  }

  set rawTrailers (value) {
    if (this.target) {
      this.target.rawTrailers = value
    }
  }
}

let warningEmitted = /** @type {boolean} */ (false)

/**
 * @typedef {Object} DecompressHandlerOptions
 * @property {number[]|Readonly<number[]>} [skipStatusCodes=[204, 304]] - List of status codes to skip decompression for
 * @property {boolean} [skipErrorResponses] - Whether to skip decompression for error responses (status codes >= 400)
 * @property {number} [maxSize=0] - Maximum output size in bytes of each decompression stage, or 0 to disable the limit
 */

class DecompressHandler extends DecoratorHandler {
  /** @type {Transform[]} */
  #decompressors = []
  /** @type {Transform|null} */
  #output = null
  /** @type {Record<string, string | string[]> | undefined} */
  #trailers
  /** @type {Readonly<number[]>} */
  #skipStatusCodes
  /** @type {boolean} */
  #skipErrorResponses
  /** @type {number} */
  #maxSize
  /** @type {number} */
  #decompressedSize = 0
  /** @type {boolean} */
  #terminated = false
  /** @type {boolean} */
  #inputEnded = false
  /** @type {boolean} */
  #outputEnded = false
  /** @type {DecompressController} */
  #controller
  /** @type {boolean} - The consumer asked us to stop pushing decoded output */
  #consumerPaused = false
  /** @type {boolean} - The decoder's writable side is full */
  #writePressure = false
  /** @type {boolean} - We paused the transport and owe it a resume */
  #transportPaused = false
  /** @type {boolean} - Guards against re-entering the read loop */
