'use strict'

const { createInflate, createGunzip, createBrotliDecompress, createZstdDecompress } = require('node:zlib')
const { pipeline, Transform: TransformStream } = require('node:stream')
const { InvalidArgumentError, ResponseExceededMaxSizeError } = require('../core/errors')
const DecoratorHandler = require('../handler/decorator-handler')

/** @typedef {import('node:stream').Transform} Transform */
/** @typedef {import('node:stream').Transform} Controller */
/** @typedef {Transform&import('node:zlib').Zlib} DecompressorStream */

/** @type {Record<string, () => DecompressorStream>} */
const supportedEncodings = {
  __proto__: null,
  gzip: createGunzip,
  'x-gzip': createGunzip,
  br: createBrotliDecompress,
  deflate: createInflate,
  compress: createInflate,
  'x-compress': createInflate,
  zstd: createZstdDecompress
}

const defaultSkipStatusCodes = /** @type {const} */ ([204, 304])
// Size policy belongs to the application, not to the transport. Backpressure
// keeps the amount of buffered decoded output tied to consumer demand, so no
// limit is needed to bound memory. `maxSize` stays available as an opt-in
// circuit breaker for callers that do want to cap a decoded body.
const defaultMaxSize = 0

/**
 * Limits the output of one stage in a decompression chain.
 * @param {number} maxSize - Maximum output size in bytes
 * @returns {Transform}
 */
function createMaxSizeLimiter (maxSize) {
  let size = 0

  return new TransformStream({
    transform (chunk, _encoding, callback) {
      const decompressedSize = size + chunk.length
      if (decompressedSize > maxSize) {
        callback(new ResponseExceededMaxSizeError(
          `Decompressed response size (${decompressedSize}) exceeded maxSize (${maxSize})`
        ))
        return
      }

      size = decompressedSize
      callback(null, chunk)
    }
  })
}

/**
 * The controller handed to the downstream handler while a response is being
 * decoded.
 *
 * Decompression splits one flow-controlled stream into two: the compressed
 * bytes arriving from the transport, and the decoded bytes leaving the decoder.
 * They pause for different reasons and must be tracked separately, so the
 * consumer gets this proxy instead of the transport controller. Its pause
 * state is owned by the consumer and lives in the handler, which leaves the
 * transport controller free to carry only the decoder's writable pressure --
 * a controller that is replaced on every retry, and whose pause state must not
 * be mistaken for the consumer's.
 *
 * Before the first response arrives -- and for responses that are not decoded
 * at all -- the proxy is inert and forwards flow control straight through.
 */
class DecompressController {
  /** @type {Controller|null} */
  target = null
  /** @type {boolean} */
  #paused = false
  /** @type {boolean} */
  #active = false
  /** @type {() => void} */
  #onPause
  /** @type {() => void} */
  #onResume

  /**
   * @param {() => void} onPause - Called when the consumer asks us to stop
   * @param {() => void} onResume - Called when the consumer asks for more
   */
  constructor (onPause, onResume) {
    this.#onPause = onPause
    this.#onResume = onResume
  }

  /**
   * Starts intercepting the consumer's flow control. Called once decompression
   * is known to be active for this response.
   * @returns {void}
   */
  activate () {
    this.#active = true
  }

  pause () {
    if (!this.#active) {
      this.target?.pause()
      return
    }

    if (!this.#paused) {
      this.#paused = true
      this.#onPause()
    }
  }

  resume () {
    if (!this.#active) {
      this.target?.resume()
      return
    }

    if (this.#paused) {
      this.#paused = false
      this.#onResume()
    }
  }

  get paused () {
    return this.#active ? this.#paused : (this.target?.paused ?? false)
  }

  abort (reason) {
    this.target?.abort(reason)
  }

  get aborted () {
    return this.target?.aborted ?? false
  }

  get reason () {
    return this.target?.reason ?? null
  }

  get rawHeaders () {
    return this.target?.rawHeaders ?? null
  }

  set rawHeaders (value) {
    if (this.target) {
      this.target.rawHeaders = value
    }
  }

  get rawTrailers () {
    return this.target?.rawTrailers ?? null
  }

  set rawTrailers (value) {
    if (this.target) {
      this.target.rawTrailers = value
    }
  }
}

let warningEmitted = /** @type {boolean} */ (false)

/**
 * @typedef {Object} DecompressHandlerOptions
 * @property {number[]|Readonly<number[]>} [skipStatusCodes=[204, 304]] - List of status codes to skip decompression for
 * @property {boolean} [skipErrorResponses] - Whether to skip decompression for error responses (status codes >= 400)
 * @property {number} [maxSize=0] - Maximum output size in bytes of each decompression stage, or 0 to disable the limit
 */

class DecompressHandler extends DecoratorHandler {
  /** @type {Transform[]} */
  #decompressors = []
  /** @type {Transform|null} */
  #output = null
  /** @type {Record<string, string | string[]> | undefined} */
  #trailers
  /** @type {Readonly<number[]>} */
  #skipStatusCodes
  /** @type {boolean} */
  #skipErrorResponses
  /** @type {number} */
  #maxSize
  /** @type {number} */
  #decompressedSize = 0
  /** @type {boolean} */
  #terminated = false
  /** @type {boolean} */
  #inputEnded = false
  /** @type {boolean} */
  #outputEnded = false
  /** @type {DecompressController} */
  #controller
  /** @type {boolean} - The consumer asked us to stop pushing decoded output */
  #consumerPaused = false
  /** @type {boolean} - The decoder's writable side is full */
  #writePressure = false
  /** @type {boolean} - We paused the transport and owe it a resume */
  #transportPaused = false
  /** @type {boolean} - Guards against re-entering the read loop */
  #reading = false

  constructor (handler, { skipStatusCodes = defaultSkipStatusCodes, skipErrorResponses = true, maxSize = defaultMaxSize } = {}) {
    if (!Number.isSafeInteger(maxSize) || maxSize < 0) {
      throw new InvalidArgumentError('maxSize must be a non-negative integer')
    }

    super(handler)
    this.#skipStatusCodes = skipStatusCodes
    this.#skipErrorResponses = skipErrorResponses
    this.#maxSize = maxSize
    this.#controller = new DecompressController(
      () => {
        // Stop reading decoded output, and stop the compressed bytes feeding it
        // rather than letting the decoder buffer them on the consumer's behalf.
        this.#consumerPaused = true
        this.#syncTransport()
      },
      () => {
        this.#consumerPaused = false
        this.#flush()
      }
    )
  }

  /**
   * Determines if decompression should be skipped based on encoding and status code
   * @param {string} contentEncoding - Content-Encoding header value
   * @param {number} statusCode - HTTP status code of the response
   * @returns {boolean} - True if decompression should be skipped
   */
  #shouldSkipDecompression (contentEncoding, statusCode) {
    if (!contentEncoding || statusCode < 200) return true
    if (this.#skipStatusCodes.includes(statusCode)) return true
    if (this.#skipErrorResponses && statusCode >= 400) return true
    return false
  }

  /**
   * Creates a chain of decompressors for multiple content encodings
   *
   * @param {string} encodings - Comma-separated list of content encodings
   * @returns {Array<Transform>} - Array of decompressor and limiting streams
   * @throws {Error} - If the number of content-encodings exceeds the maximum allowed
   */
  #createDecompressionChain (encodings) {
    const parts = encodings.split(',')

    // Limit the number of content-encodings to prevent resource exhaustion.
    // CVE fix similar to urllib3 (GHSA-gm62-xv2j-4w53) and curl (CVE-2022-32206).
    const maxContentEncodings = 5
    if (parts.length > maxContentEncodings) {
      throw new Error(`too many content-encodings in response: ${parts.length}, maximum allowed is ${maxContentEncodings}`)
    }

    /** @type {DecompressorStream[]} */
    const decompressors = []

    for (let i = parts.length - 1; i >= 0; i--) {
      const encoding = parts[i].trim()
      if (!encoding) continue

      if (!supportedEncodings[encoding]) {
        decompressors.length = 0 // Clear if unsupported encoding
        return decompressors // Unsupported encoding
      }

      decompressors.push(supportedEncodings[encoding]())
    }

    if (decompressors.length < 2 || this.#maxSize === 0) {
      return decompressors
    }

    /** @type {Transform[]} */
    const streams = []
    for (let i = 0; i < decompressors.length; i++) {
      streams.push(decompressors[i])
      if (i < decompressors.length - 1) {
        streams.push(createMaxSizeLimiter(this.#maxSize))
      }
    }

    return streams
  }

  /**
   * Mirrors the current pause reasons onto the transport.
   *
   * The pause is re-asserted on every call because a retry dispatches on a
   * fresh connection whose controller starts unpaused; only a resume we own is
   * ever sent, so the consumer's own pause is never cleared by accident.
   * @returns {void}
   */
  #syncTransport () {
    const target = this.#controller.target
    if (target === null || this.#terminated) {
      return
    }

    if (this.#writePressure || this.#consumerPaused) {
      this.#transportPaused = true
      target.pause()
    } else if (this.#transportPaused) {
      this.#transportPaused = false
      target.resume()
    }
  }

  /**
   * Stops decompression and reports an error.
   * @param {Error} error - The decompression error
   * @returns {void}
   */
  #fail (error) {
    if (this.#terminated) {
      return
    }

    if (this.#inputEnded) {
      // The request is already marked complete once the compressed input ends,
      // so controller.abort() can no longer propagate decoder flush errors.
      this.onResponseError(this.#controller.target, error)
    } else {
      this.#controller.abort(error)
    }
  }

  /**
   * Pushes decoded output downstream for as long as the consumer wants it.
   * @returns {void}
   */
  #flush () {
    if (!this.#terminated && !this.#reading && this.#output !== null) {
      const output = this.#output
      this.#reading = true

      try {
        let chunk
        while (!this.#consumerPaused && (chunk = output.read()) !== null) {
          const decompressedSize = this.#decompressedSize + chunk.length
          if (this.#maxSize !== 0 && decompressedSize > this.#maxSize) {
            this.#reading = false
            this.#fail(new ResponseExceededMaxSizeError(
              `Decompressed response size (${decompressedSize}) exceeded maxSize (${this.#maxSize})`
            ))
            return
          }

          this.#decompressedSize = decompressedSize
          super.onResponseData(this.#controller, chunk)
        }
      } finally {
        this.#reading = false
      }
    }

    this.#maybeComplete()
    this.#syncTransport()
  }

  /**
   * Signals completion once the decoder is done and the consumer has taken
   * everything it produced.
   * @returns {void}
   */
  #maybeComplete () {
    if (this.#terminated || !this.#outputEnded || this.#consumerPaused) {
      return
    }

    if (this.#output !== null && this.#output.readableLength > 0) {
      return
    }

    this.#terminated = true
    this.#output = null
    this.#cleanupDecompressors()
    super.onResponseEnd(this.#controller, this.#trailers)
  }

  /**
   * Sets up event handlers for a decompressor stream using readable events
   * @param {DecompressorStream} decompressor - The decompressor stream
   * @returns {void}
   */
  #setupDecompressorEvents (decompressor) {
    this.#output = decompressor

    decompressor.on('readable', () => {
      this.#flush()
    })

    decompressor.on('error', (error) => {
      this.#fail(error)
    })
  }

  /**
   * Sets up event handling for a single decompressor
   * @returns {void}
   */
  #setupSingleDecompressor () {
    const decompressor = this.#decompressors[0]
    this.#setupDecompressorEvents(decompressor)

    decompressor.on('end', () => {
      this.#outputEnded = true
      this.#maybeComplete()
    })
  }

  /**
   * Sets up event handling for multiple chained decompressors using pipeline
   * @returns {void}
   */
  #setupMultipleDecompressors () {
    const lastDecompressor = this.#decompressors[this.#decompressors.length - 1]
    this.#setupDecompressorEvents(lastDecompressor)

    pipeline(this.#decompressors, (err) => {
      if (this.#terminated) {
        return
      }

      if (err) {
        this.#fail(err)
        return
      }

      this.#outputEnded = true
      this.#maybeComplete()
    })
  }

  /**
   * Cleans up decompressor references to prevent memory leaks
   * @returns {void}
   */
  #cleanupDecompressors () {
    this.#decompressors.length = 0
  }

  /**
   * @param {Controller} controller
   * @param {unknown} context
   * @returns {void}
   */
  onRequestStart (controller, context) {
    this.#controller.target = controller
    return super.onRequestStart(this.#controller, context)
  }

  /**
   * @param {Controller} controller
   * @param {number} statusCode
   * @param {Record<string, string | string[] | undefined>} headers
   * @param {string} statusMessage
   * @returns {void}
   */
