  // Once the response is done the transport must never be left paused by us,
  // whatever the pause reasons still say.
  if (!this.#terminated && (this.#writePressure || this.#consumerPaused)) {
    this.#transportPaused = true
    target.pause()
  } else if (this.#transportPaused) {
    this.#transportPaused = false
    target.resume()
  }
}

/**
 * Stops decompression and reports an error.
 * @param {Error} error - The decompression error
 * @returns {void}
 */
#fail (error) {
  if (this.#terminated) {
    return
  }

  if (this.#inputEnded) {
    // The request is already marked complete once the compressed input ends,
    // so controller.abort() can no longer propagate decoder flush errors.
    this.onResponseError(this.#controller.target, error)
  } else {
    this.#controller.abort(error)
  }
}

/**
 * Pushes decoded output downstream for as long as the consumer wants it.
 * @returns {void}
 */
#flush () {
  if (!this.#terminated && !this.#reading && this.#output !== null) {
    const output = this.#output
    this.#reading = true

    try {
      let chunk
      while (!this.#consumerPaused && (chunk = output.read()) !== null) {
        const decompressedSize = this.#decompressedSize + chunk.length
        if (this.#maxSize !== 0 && decompressedSize > this.#maxSize) {
          this.#reading = false
          this.#fail(new ResponseExceededMaxSizeError(
            `Decompressed response size (${decompressedSize}) exceeded maxSize (${this.#maxSize})`
          ))
          return
        }

        this.#decompressedSize = decompressedSize
        super.onResponseData(this.#controller, chunk)
      }
    } finally {
      this.#reading = false
    }
  }

