test('should not limit the decompressed size by default', async t => {
  t = tspl(t, { plan: 2 })

  // Comfortably past the 64 MiB cap the interceptor used to impose.
  const chunk = Buffer.alloc(1024 * 1024, 0x61)
  const chunks = 80
  const server = createServer({ joinDuplicateHeaders: true }, async (req, res) => {
    const gzip = createGzip()
    res.writeHead(200, {
      'Content-Type': 'text/plain',
      'Content-Encoding': 'gzip'
    })

    gzip.pipe(res)
    for (let i = 0; i < chunks; i++) {
      if (!gzip.write(chunk)) {
        await once(gzip, 'drain')
      }
    }
    gzip.end()
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(createDecompressInterceptor())

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  const response = await client.request({
    method: 'GET',
    path: '/'
  })

  let received = 0
  for await (const part of response.body) {
    received += part.length
  }

  t.equal(response.statusCode, 200)
  t.equal(received, chunk.length * chunks)

  await t.completed
})

test('should stop pushing decoded output while the consumer is paused', async t => {
  t = tspl(t, { plan: 4 })

  const data = Buffer.alloc(4 * 1024 * 1024, 0x62)
  const server = createServer({ joinDuplicateHeaders: true }, async (req, res) => {
    const gzip = createGzip()
    res.writeHead(200, {
      'Content-Type': 'text/plain',
      'Content-Encoding': 'gzip'
    })

    gzip.pipe(res)
    gzip.end(data)
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(createDecompressInterceptor())

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  let controller
  let received = 0
  let paused = false
  let deliveredWhilePaused = 0
  let endedWhilePaused = false
  let resumed = false

  const handler = {
    onRequestStart (ctrl) {
      controller = ctrl
    },

    onResponseStart (ctrl, statusCode) {
      t.equal(statusCode, 200)
    },

    onResponseData (ctrl, chunk) {
      received += chunk.length

      if (paused) {
        deliveredWhilePaused += chunk.length
        return
      }

      if (!resumed) {
        // Hold the response open for a while and make sure nothing else is
        // pushed at us, and that the response is not completed behind our back.
        paused = true
        controller.pause()
        setTimeout(() => {
          paused = false
          resumed = true
          controller.resume()
        }, 200)
      }
    },

    onResponseEnd () {
      endedWhilePaused = paused
    },

    onResponseError (ctrl, err) {
      t.fail(err)
    }
  }

  await client.dispatch({ method: 'GET', path: '/' }, handler)

  // Let the paused window elapse before asserting.
  await new Promise(resolve => setTimeout(resolve, 500))

  t.equal(deliveredWhilePaused, 0, 'no data should be delivered while paused')
  t.equal(endedWhilePaused, false, 'completion should wait for the consumer')
  t.equal(received, data.length, 'all data should eventually arrive')

  await t.completed
})

test('should propagate decoder write pressure to the transport', async t => {
  t = tspl(t, { plan: 3 })

  const data = Buffer.alloc(8 * 1024 * 1024, 0x63)
  const server = createServer({ joinDuplicateHeaders: true }, async (req, res) => {
    const gzip = createGzip()
    res.writeHead(200, {
      'Content-Type': 'text/plain',
      'Content-Encoding': 'gzip'
    })

    gzip.pipe(res)
    gzip.end(data)
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(createDecompressInterceptor())

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  let transportController
  let transportPaused = false

  const handler = {
    onRequestStart (ctrl) {
      // The consumer talks to the interceptor's controller; the transport
      // controller underneath it is the one that carries write pressure.
      transportController = ctrl.target
      const pause = transportController.pause.bind(transportController)
      transportController.pause = () => {
        transportPaused = true
        pause()
      }
    },

    onResponseStart (ctrl, statusCode) {
      t.equal(statusCode, 200)
      // Never read the decoded output until the very end, which backs up the
      // decoder and must stall the socket rather than buffer without bound.
      ctrl.pause()
      setTimeout(() => ctrl.resume(), 200)
    },

    onResponseData (ctrl, chunk) {
      this.received = (this.received ?? 0) + chunk.length
    },

    onResponseEnd () {
      t.equal(this.received, data.length)
    },

    onResponseError (ctrl, err) {
      t.fail(err)
    }
  }

  await client.dispatch({ method: 'GET', path: '/' }, handler)
  await new Promise(resolve => setTimeout(resolve, 500))

  t.ok(transportPaused, 'the transport should have been paused')

  await t.completed
})
